const envelope = $json.body || $json;
if (envelope.event !== 'booking.created' || !envelope.eventId || !envelope.data) {
  throw new Error('Expected a valid booking.created event');
}
const d = envelope.data;
if (!d.bookingCode || !d.email || !d.adminEmail) {
  throw new Error('Booking code, customer email, and BOOKING_ADMIN_EMAIL are required');
}
const esc = (value = '') => String(value).replace(/[&<>\"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char]));
const date = new Date(d.date).toLocaleDateString('en-IN', { day: '2-digit', month: 'long', year: 'numeric', timeZone: 'Asia/Kolkata' });
const mode = d.testDriveMode === 'home' ? 'Home test drive' : 'Showroom visit';
const address = d.testDriveMode === 'home' ? esc(d.address) : esc(d.location || 'Nearest showroom to be confirmed');
const row = (label, value) => `<tr><td style=\"padding:7px 10px;color:#64748b\">${label}</td><td style=\"padding:7px 10px;color:#111827;font-weight:600\">${value || '—'}</td></tr>`;
const table = [row('Booking ID', esc(d.bookingCode)), row('Customer', esc(d.name)), row('Phone', esc(d.phone)), row('Email', esc(d.email)), row('EV', esc(d.vehicle)), row('Requested date', date), row('Time', esc(d.timeSlot)), row('Drive type', mode), row('City / PIN', `${esc(d.city)} / ${esc(d.pincode)}`), row('Location', address), row('Notes', esc(d.notes))].join('');
const shell = (title, intro, body, footer) => `<div style=\"font-family:Arial,sans-serif;background:#f4f7fb;padding:24px\"><div style=\"max-width:640px;margin:auto;background:white;border-radius:16px;overflow:hidden;border:1px solid #e5e7eb\"><div style=\"background:#07111f;color:white;padding:22px 26px\"><div style=\"color:#38bdf8;font-size:12px;font-weight:700;letter-spacing:.08em\">TATAEV TEST DRIVE</div><h2 style=\"margin:7px 0 0\">${title}</h2></div><div style=\"padding:24px 26px;color:#334155;line-height:1.6\"><p>${intro}</p>${body}<p style=\"font-size:12px;color:#64748b;margin-top:22px\">${footer}</p></div></div></div>`;
const adminHtml = shell('New test-drive request', `A new request has been submitted by <strong>${esc(d.name)}</strong>.`, `<table style=\"width:100%;border-collapse:collapse;background:#f8fafc;border-radius:10px\">${table}</table>`, 'Contact the customer and verify vehicle, executive, and slot availability before marking this booking confirmed.');
const customerHtml = shell('We received your request', `Hi ${esc(d.name)}, we have received your test-drive request for <strong>${esc(d.vehicle)}</strong>.`, `<div style=\"background:#eff6ff;border:1px solid #bfdbfe;border-radius:12px;padding:16px;margin:18px 0\"><strong>Booking ID:</strong> ${esc(d.bookingCode)}<br><strong>Preferred date:</strong> ${date}<br><strong>Preferred time:</strong> ${esc(d.timeSlot)}<br><strong>Preference:</strong> ${mode}</div><p>This is an acknowledgement, not the final slot confirmation. Our dealership team will contact you after checking availability.</p>`, 'Please do not share OTPs, passwords, or payment information in reply to an unverified request.');
const slackText = `🚗 *New test-drive request*\n*${d.bookingCode}* • ${d.vehicle || 'EV not selected'}\nCustomer: ${d.name}\nPhone: ${d.phone}\nEmail: ${d.email}\nRequested: ${date}, ${d.timeSlot}\nMode: ${mode}\nArea: ${d.city} - ${d.pincode}\nStatus: Pending dealership confirmation`;
return [{ json: { ...envelope, data: d, adminHtml, customerHtml, slackText } }];
